<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {Plus,RefreshCw,History,X,Trash2,Pencil} from 'lucide-vue-next'
import {api,type CapabilityControl,type CapabilityVersion,type SkillDeclaration,type HttpToolDeclaration,type SqlPolicy} from '../api'
import {useAppStore} from '../store'
const store=useAppStore(),plane=ref<CapabilityControl|null>(null),error=ref(''),notice=ref(''),loading=ref(false),busy=ref(false),kind=ref<'skills'|'tools'>('skills'),editor=ref<HTMLDialogElement>(),confirmation=ref<HTMLDialogElement>(),history=ref<CapabilityVersion[]>([]),moreHistory=ref(true),showHistory=ref(false),expanded=ref<number|null>(null)
const editing=ref(false),editRevision=ref(0),name=ref(''),description=ref(''),enabled=ref(true),roles=ref<string[]>([]),instructions=ref(''),allowedTools=ref<string[]>([]),requiredSecrets=ref<string[]>([]),group=ref('public'),endpoint=ref(''),method=ref<'GET'|'POST'>('GET'),schema=ref(''),staticHeaders=ref('{}'),secretHeaders=ref('{}'),approval=ref(false),idempotent=ref(true),timeout=ref(20),responseBytes=ref(262144),formError=ref(''),deleteName=ref(''),deleteRevision=ref(0)
const records=computed(()=>Object.entries(kind.value==='skills'?plane.value?.catalog.skills||{}:plane.value?.catalog.tools||{}))
const toolNames=computed(()=>[...Object.keys(plane.value?.builtin_tools||{}),...Object.keys(plane.value?.catalog.tools||{})])
const runtimeEditor=ref<HTMLDialogElement>(),runtimeComponent=ref<'sql'|'web'>('sql'),runtimeRevision=ref(0),sqlForm=ref<SqlPolicy>({enabled:false,allowed_tables:[],source_name:'业务数据库',timeout_seconds:5,max_rows:100}),tableInput=ref(''),webEnabled=ref(true)
function openRuntime(component:'sql'|'web'){if(!plane.value)return;runtimeComponent.value=component;runtimeRevision.value=plane.value.revision;formError.value='';sqlForm.value={...plane.value.runtime.sql,allowed_tables:[...plane.value.runtime.sql.allowed_tables]};tableInput.value=sqlForm.value.allowed_tables.join('\n');webEnabled.value=plane.value.runtime.web.enabled;runtimeEditor.value?.showModal()}
async function saveRuntime(){if(busy.value||!plane.value)return;busy.value=true;formError.value='';const owner=identity();try{const declaration=runtimeComponent.value==='web'?{enabled:webEnabled.value}:{...sqlForm.value,allowed_tables:tableInput.value.split(/\s+/).filter(Boolean)};const result=await api.saveCapabilityRuntime(runtimeComponent.value,declaration,runtimeRevision.value);if(owner!==identity())return;runtimeEditor.value?.close();notice.value=`运行配置已保存到目录修订 ${result.revision}`;await load();const flags=await api.capabilities();if(owner!==identity())return;store.capabilities=flags;void store.loadCapabilityDirectory().catch(()=>{});if(showHistory.value)void loadHistory(true)}catch(e:any){if(owner===identity())formError.value=e.message}finally{busy.value=false}}
function identity(){return `${store.user?.id}/${store.organizationId}`}
async function load(){const owner=identity();loading.value=true;error.value='';try{const value=await api.capabilityControl();if(owner===identity())plane.value=value}catch(e:any){if(owner===identity())error.value=e.message}finally{if(owner===identity())loading.value=false}}
let historyAttempt=0
async function loadHistory(reset=false){const attempt=++historyAttempt;const owner=identity();try{const offset=reset?0:history.value.length;const page=await api.capabilityHistory(offset);if(owner!==identity()||attempt!==historyAttempt)return;history.value=reset?page.items:[...history.value,...page.items];moreHistory.value=page.items.length===20}catch(e:any){if(owner===identity()&&attempt===historyAttempt)error.value=e.message}}
function open(nameToEdit?:string){
  if(!plane.value)return
  formError.value='';editing.value=!!nameToEdit;editRevision.value=plane.value.revision
  name.value=nameToEdit||'';description.value='';enabled.value=true;roles.value=[]
  instructions.value='';allowedTools.value=[];requiredSecrets.value=[];group.value='public';endpoint.value='';method.value='GET';schema.value=JSON.stringify({type:'object',properties:{},additionalProperties:false},null,2);staticHeaders.value='{}';secretHeaders.value='{}';approval.value=false;idempotent.value=true;timeout.value=20;responseBytes.value=262144
  if(nameToEdit){
    const row=kind.value==='skills'?plane.value.catalog.skills[nameToEdit]:plane.value.catalog.tools[nameToEdit]
    const value=row.declaration
    description.value=value.description;enabled.value=value.enabled;roles.value=[...value.required_roles]
    if('instructions' in value){instructions.value=value.instructions;allowedTools.value=[...value.allowed_tools];requiredSecrets.value=[...value.required_secrets]}
    else{group.value=value.group;endpoint.value=value.endpoint;method.value=value.method;schema.value=JSON.stringify(value.input_schema,null,2);staticHeaders.value=JSON.stringify(value.static_headers,null,2);secretHeaders.value=JSON.stringify(value.secret_headers,null,2);approval.value=value.requires_approval;idempotent.value=value.idempotent;timeout.value=value.timeout_seconds;responseBytes.value=value.max_response_bytes}
  }
  editor.value?.showModal()
}
function object(text:string,label:string){let value;try{value=JSON.parse(text)}catch{throw new Error(`${label}不是有效的 JSON`)}if(!value||typeof value!=='object'||Array.isArray(value))throw new Error(`${label}必须是 JSON 对象`);return value}
async function save(){
  if(busy.value||!plane.value)return
  busy.value=true;formError.value='';notice.value='';const owner=identity()
  try{
    const common={name:name.value,description:description.value,enabled:enabled.value,required_roles:roles.value}
    const declaration:SkillDeclaration|HttpToolDeclaration=kind.value==='skills'?{...common,instructions:instructions.value,allowed_tools:allowedTools.value,required_secrets:requiredSecrets.value}:{...common,group:group.value,endpoint:endpoint.value,method:method.value,input_schema:object(schema.value,'参数 Schema'),static_headers:object(staticHeaders.value,'固定请求头'),secret_headers:object(secretHeaders.value,'Secret 请求头'),requires_approval:approval.value,idempotent:idempotent.value,timeout_seconds:timeout.value,max_response_bytes:responseBytes.value}
    const value=await api.saveCapability(kind.value,declaration,editRevision.value,!editing.value)
    if(owner!==identity())return
    plane.value={...plane.value,...value};editor.value?.close();notice.value=`已保存到目录修订 ${value.revision}`
    void store.loadCapabilityDirectory().catch(()=>{});if(showHistory.value)void loadHistory(true)
  }catch(e:any){if(owner===identity())formError.value=e.message}finally{busy.value=false}
}
function askDelete(name:string){deleteName.value=name;deleteRevision.value=plane.value?.revision||0;formError.value='';confirmation.value?.showModal()}
async function remove(){if(busy.value||!plane.value)return;busy.value=true;formError.value='';const owner=identity();try{const result=await api.deleteCapability(kind.value,deleteName.value,deleteRevision.value);if(owner!==identity())return;plane.value={...plane.value,...result};confirmation.value?.close();notice.value=`已删除 ${deleteName.value}，历史版本继续保留`;void store.loadCapabilityDirectory().catch(()=>{});if(showHistory.value)void loadHistory(true)}catch(e:any){if(owner===identity())formError.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="documents capability-admin">
  <header class="admin-heading"><div><small>CAPABILITY CONTROL</small><h1>Skill / Tool 管理</h1><p>管理能力定义和版本。运行中的任务保留原版本，停用与撤权会阻止后续调用。</p></div><RouterLink class="secondary" to="/capabilities">查看能力中心</RouterLink></header>
  <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p>
  <section v-if="plane" class="runtime-controls" aria-label="内置工具配置"><h2>内置工具配置</h2><p class="muted">SQL 使用服务端独立只读连接；保存启用配置时会核验权限和表。网页开关控制内置搜索及页面读取，自定义 HTTP Tool 单独管理。</p><button class="secondary" :disabled="busy||loading" @click="openRuntime('sql')">配置 SQL · {{plane.runtime.sql.enabled?'已启用':'未启用'}}</button><button class="secondary" :disabled="busy||loading" @click="openRuntime('web')">配置网页能力 · {{plane.runtime.web.enabled?'已启用':'已停用'}}</button></section>
  <div class="admin-toolbar"><div role="tablist" aria-label="管理类型"><button role="tab" :aria-selected="kind==='skills'" :class="{active:kind==='skills'}" @click="kind='skills'">Skill</button><button role="tab" :aria-selected="kind==='tools'" :class="{active:kind==='tools'}" @click="kind='tools'">HTTP Tool</button></div><span v-if="plane">目录修订 {{plane.revision}}</span><button class="ghost" :disabled="loading||busy" @click="load"><RefreshCw :size="15"/>刷新</button><button class="primary" :disabled="!plane||loading" @click="open()"><Plus :size="16"/>新增 {{kind==='skills'?'Skill':'Tool'}}</button></div>
  <p v-if="loading" role="status">正在读取目录…</p><div v-else-if="plane" class="table-wrap"><table><thead><tr><th>名称 / 说明</th><th>版本</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="[name,item] in records" :key="name"><td><strong>{{name}}</strong><small>{{item.declaration.description}}</small></td><td>v{{item.version}}<small v-if="'source' in item">{{item.source==='builtin'?'内置 Skill':'自定义'}}</small></td><td>{{item.declaration.enabled?'已启用':'已停用'}}</td><td><div class="row-actions"><button class="ghost" :aria-label="`编辑 ${name}`" @click="open(name)"><Pencil :size="14"/>编辑</button><button class="ghost danger" :aria-label="`删除 ${name}`" @click="askDelete(name)"><Trash2 :size="14"/>删除</button></div></td></tr><tr v-if="!records.length"><td colspan="4">还没有注册 {{kind==='skills'?'Skill':'HTTP Tool'}}。</td></tr></tbody></table></div>
  <p v-if="kind==='tools'" class="muted">内置 RAG / SQL / Web 工具由服务提供，不能覆盖或删除。自定义工具只能调用公共 HTTPS JSON 服务，不执行上传代码。</p>
  <section class="history-section"><button class="secondary" @click="showHistory=!showHistory;showHistory&&loadHistory(true)"><History :size="15"/>{{showHistory?'收起':'查看'}}版本历史</button><template v-if="showHistory"><article v-for="version in history" :key="version.revision"><button class="history-row" :aria-expanded="expanded===version.revision" @click="expanded=expanded===version.revision?null:version.revision"><strong>修订 {{version.revision}}</strong><span>{{version.change.operation}} {{version.change.name||''}}</span><small>{{new Date(version.created_at).toLocaleString()}}</small></button><pre v-if="expanded===version.revision">{{JSON.stringify({created_by:version.created_by,catalog:version.catalog},null,2)}}</pre></article><button v-if="moreHistory" class="ghost" @click="loadHistory()">加载更多历史</button><p v-if="!history.length" class="muted">暂无历史记录。</p></template></section>
  <dialog ref="editor" class="capability-editor" aria-labelledby="capability-editor-title" @cancel="busy&&$event.preventDefault()"><header><div><small>基于目录修订 {{editRevision}}</small><h2 id="capability-editor-title">{{editing?'编辑':'新增'}} {{kind==='skills'?'Skill':'HTTP Tool'}}</h2></div><button class="icon" aria-label="关闭编辑" :disabled="busy" @click="editor?.close()"><X/></button></header><form @submit.prevent="save"><fieldset :disabled="busy"><div class="form-grid"><label>标识<input v-model="name" required :disabled="editing" :maxlength="kind==='skills'?64:128" :pattern="kind==='skills'?'[a-z0-9]+(-[a-z0-9]+)*':'[a-z][a-z0-9_.-]*'" placeholder="例如 public-research"/></label><label>说明<input v-model="description" required :maxlength="kind==='skills'?500:1000"/></label></div><label class="check"><input v-model="enabled" type="checkbox"/>启用此{{kind==='skills'?'能力':'工具'}}</label><div class="roles"><span>可使用角色（不选表示全部）</span><label class="check"><input v-model="roles" type="checkbox" value="user"/>普通用户</label><label class="check"><input v-model="roles" type="checkbox" value="admin"/>平台管理员</label></div>
    <template v-if="kind==='skills'"><label>能力指令<textarea v-model="instructions" required rows="8" maxlength="262144" placeholder="说明如何使用工具、核对结果与引用来源"/></label><label>允许使用的工具<select v-model="allowedTools" multiple size="5"><option v-for="tool in toolNames" :key="tool" :value="tool">{{tool}}</option></select></label><p class="muted">工具仍受原有资料权限、公开输入和执行预算约束。工具被停用时，引用它的已启用 Skill 需先调整。</p><label v-if="plane?.secret_names.length">所需 Secret 名称<select v-model="requiredSecrets" multiple><option v-for="secret in plane.secret_names" :key="secret">{{secret}}</option></select></label></template>
    <template v-else><div class="form-grid"><label>分组<input v-model="group" required pattern="[a-z][a-z0-9_.-]*" maxlength="128"/></label><label>方法<select v-model="method"><option>GET</option><option>POST</option></select></label></div><label>公共 HTTPS 地址<input v-model="endpoint" type="url" required maxlength="2048" placeholder="https://api.example.com/lookup"/></label><label>参数 Schema（JSON Schema 2020-12）<textarea v-model="schema" class="code-input" rows="7" required/></label><div class="form-grid"><label>固定请求头（JSON）<textarea v-model="staticHeaders" class="code-input" rows="4"/></label><label>Secret 请求头引用（JSON，仅名称）<textarea v-model="secretHeaders" class="code-input" rows="4" placeholder='{"Authorization":"PUBLIC_API_TOKEN"}'/></label></div><p class="muted">可引用名称：{{plane?.secret_names.join('、')||'未配置允许的名称'}}。凭据值只保存在服务端环境中。</p><div class="form-grid"><label>超时（秒）<input v-model.number="timeout" type="number" min="0.1" max="120" step="0.1" required/></label><label>响应上限（字节）<input v-model.number="responseBytes" type="number" min="1024" max="8388608" required/></label></div><label class="check"><input v-model="idempotent" type="checkbox"/>幂等调用，可在结果未确认时安全重试</label><label class="check"><input v-model="approval" type="checkbox"/>需要审批（当前审批链路尚未开放，该工具将不可执行）</label></template>
    <p v-if="formError" class="error" role="alert">{{formError}}</p><footer><button type="button" class="secondary" @click="editor?.close()">取消</button><button class="primary" type="submit">{{busy?'正在保存…':'保存新版本'}}</button></footer></fieldset></form></dialog>
  <dialog ref="confirmation" class="delete-dialog" aria-labelledby="delete-capability-title" @cancel="busy&&$event.preventDefault()"><h2 id="delete-capability-title">删除 {{deleteName}}？</h2><p>历史版本继续保留，当前目录将不再提供此项。仍有 Skill 引用的工具不能删除。</p><p v-if="formError" class="error" role="alert">{{formError}}</p><footer><button class="secondary" :disabled="busy" @click="confirmation?.close()">取消</button><button class="primary" :disabled="busy" @click="remove">{{busy?'正在删除…':'确认删除'}}</button></footer></dialog>
  <dialog ref="runtimeEditor" class="capability-editor" aria-labelledby="runtime-editor-title" @cancel="busy&&$event.preventDefault()"><header><h2 id="runtime-editor-title">{{runtimeComponent==='sql'?'SQL 只读配置':'网页能力配置'}}</h2><button class="icon" aria-label="关闭运行配置" :disabled="busy" @click="runtimeEditor?.close()"><X/></button></header><p class="muted">基于目录修订 {{runtimeRevision}}，保存后生成新版本。</p><form @submit.prevent="saveRuntime"><fieldset :disabled="busy"><template v-if="runtimeComponent==='sql'"><p class="muted">只读连接{{plane?.runtime.sql_connection_configured?'已在服务端配置':'尚未在服务端配置，启用前需先配置'}}。页面不接收或显示连接凭据。</p><label class="check"><input v-model="sqlForm.enabled" type="checkbox"/>启用 SQL 工具</label><label>来源名称<input v-model="sqlForm.source_name" required maxlength="100"/></label><label>允许查询的表（每行一个 schema.table）<textarea v-model="tableInput" rows="6" placeholder="business.products" :required="sqlForm.enabled"/></label><div class="form-grid"><label>查询超时（秒）<input v-model.number="sqlForm.timeout_seconds" type="number" min="0.1" max="30" step="0.1" required/></label><label>返回行数上限<input v-model.number="sqlForm.max_rows" type="number" min="1" max="100" required/></label></div></template><template v-else><label class="check"><input v-model="webEnabled" type="checkbox"/>启用内置网页工具</label><p class="muted">公共页面读取沿用地址和网络校验。搜索服务{{plane?.runtime.web_search_configured?'已配置':'尚未配置，开启后仍只能读取明确提供的公共页面'}}。</p></template><p v-if="formError" class="error" role="alert">{{formError}}</p><footer><button class="secondary" type="button" @click="runtimeEditor?.close()">取消</button><button class="primary" type="submit">{{busy?'正在核验并保存…':'保存运行配置'}}</button></footer></fieldset></form></dialog>
</section></template>
<style scoped>
.capability-admin{max-width:1250px}.admin-heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.admin-heading small{letter-spacing:.14em;font-size:10px;color:var(--green)}h1{font-family:'Noto Serif SC',serif;font-size:34px;margin:12px 0}.admin-heading p,.muted{font-size:12px;line-height:1.9;color:var(--muted)}.admin-heading a{text-decoration:none;font-size:12px}.admin-toolbar{display:flex;gap:12px;align-items:center;margin:28px 0}.admin-toolbar [role=tablist]{display:flex;gap:6px}.admin-toolbar [role=tab]{border:1px solid var(--line);background:transparent;color:var(--muted);padding:10px 16px;border-radius:6px}.admin-toolbar [role=tab].active{background:var(--green);color:white;border-color:var(--green)}.admin-toolbar>span{margin-right:auto;font-size:11px;color:var(--muted)}td small{display:block;max-width:500px;margin-top:7px;font-size:11px;color:var(--muted);overflow-wrap:anywhere}td strong{overflow-wrap:anywhere}.row-actions{display:flex;gap:6px}.danger,.error{color:var(--red)}.notice{padding:14px;background:var(--green2);color:var(--green);font-size:13px}.error{font-size:12px;line-height:1.8}.history-section{margin-top:35px;border-top:1px solid var(--line);padding-top:24px}.history-section article{border-bottom:1px solid var(--line)}.history-row{display:flex;gap:16px;align-items:center;text-align:left;width:100%;padding:17px 0;border:0;background:transparent;color:var(--ink)}.history-row small{margin-left:auto;color:var(--muted)}.history-row span{font-size:12px}.history-section pre{max-height:400px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px;background:var(--surface);padding:18px}dialog{background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:12px;padding:28px;max-height:88vh;overflow:auto}dialog::backdrop{background:#102c2266;backdrop-filter:blur(3px)}.capability-editor{width:min(780px,94vw)}.capability-editor header{display:flex;justify-content:space-between;gap:20px;align-items:center}.capability-editor header small{font-size:10px;color:var(--muted)}dialog h2{font-family:'Noto Serif SC',serif;font-size:25px;margin:8px 0 20px}fieldset{border:0;padding:0;margin:0;min-width:0}form label{display:grid;gap:8px;margin:16px 0;font-size:12px}input:not([type=checkbox]),textarea,select{min-width:0;max-width:100%;width:100%;font:inherit;border:1px solid var(--line);border-radius:6px;background:transparent;color:var(--ink);padding:10px}textarea{resize:vertical;line-height:1.8}.code-input{font-family:monospace;font-size:12px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.check{display:flex;gap:9px;align-items:center}.roles{display:flex;gap:18px;flex-wrap:wrap;align-items:center;font-size:12px}.roles>span{color:var(--muted)}footer{display:flex;justify-content:flex-end;gap:10px;margin-top:22px}.delete-dialog{width:min(460px,92vw)}.delete-dialog p{font-size:13px;line-height:1.9;color:var(--muted)}button:disabled,fieldset:disabled{opacity:.55;cursor:not-allowed}@media(max-width:760px){.capability-admin th:nth-child(4),.capability-admin td:nth-child(4){display:table-cell}.capability-admin table{min-width:0;table-layout:fixed}.capability-admin th,.capability-admin td{padding:12px 6px}.capability-admin th:first-child{width:44%}.capability-admin th:nth-child(2){width:12%}.capability-admin th:nth-child(3){width:14%}.capability-admin th:nth-child(4){width:30%}.admin-heading{align-items:flex-start;flex-direction:column}.admin-toolbar{flex-wrap:wrap}.form-grid{grid-template-columns:1fr}.row-actions{flex-direction:column}.history-row{align-items:flex-start;flex-wrap:wrap}}
</style>
